import { describe, test, expect } from 'bun:test';
import { sha512_256 } from './sha512_256.js';
import { sha512 } from './sha512.js';
import { bitArray } from '../utils/bitArray.js';
import { utf8 } from '../../io/codec/utf8.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _utf8 = utf8.factory();
const _hex = hex.factory();
const _sha512 = sha512.factory(_ba, _utf8);
const _h = sha512_256.factory(_sha512);

const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));

// Build a bitArray of `len` bits from a hex msg, padding the trailing partial
// word with `bitArray.partial`. Mirrors the helper used in sha224/sha384 ACVP.
function hexToBitArray(hexStr, lenBits) {
    if (lenBits === 0) return [];
    const bytes = _hex.toBytes(hexStr);
    const fullBytes = lenBits >>> 3;
    const tailBits = lenBits & 7;
    const ba = _ba.ui8_to_ba(bytes.subarray(0, fullBytes + (tailBits ? 1 : 0)));
    if (tailBits) {
        // ui8_to_ba already uses partial encoding for the trailing word;
        // ensure exact bit count via clamp.
        return _ba.clamp(ba, lenBits);
    }
    return ba;
}

describe('sha512_256 module (FIPS 180-4 §5.3.6.2)', () => {

    test('module metadata', () => {
        expect(sha512_256.name).toBe('sha512_256');
        expect(sha512_256.dependencies).toEqual(['sha512']);
    });

    test('exposes HMAC contract: { name, fn, hash, fn.prototype.{blockSize, update, finalize} }', () => {
        expect(typeof _h.fn).toBe('function');
        expect(typeof _h.hash).toBe('function');
        expect(_h.fn.prototype.blockSize).toBe(1024);
        expect(typeof _h.fn.prototype.update).toBe('function');
        expect(typeof _h.fn.prototype.finalize).toBe('function');
    });

    test('digest is exactly 256 bits (8 × 32-bit words)', () => {
        const out = _h.hash('abc');
        expect(out.length).toBe(8);
    });

    test('digest differs from SHA-512 truncated (IV binding)', () => {
        // SHA-512/256 ≠ SHA-512("abc")[0..32] because the IV is distinct.
        const fullSha512 = _sha512.hash('abc');
        const truncated = _h.hash('abc');
        // Compare first 8 words: should differ.
        let allEqual = true;
        for (let i = 0; i < 8; i++) {
            if (truncated[i] !== fullSha512[i]) { allEqual = false; break; }
        }
        expect(allEqual).toBe(false);
    });

    test('streaming = one-shot (3-chunk update)', () => {
        const data = new Uint8Array(300);
        for (let i = 0; i < 300; i++) data[i] = (i * 13 + 7) & 0xff;
        const oneShot = _h.hash(_ba.ui8_to_ba(data));
        const streamed = new _h.fn()
            .update(_ba.ui8_to_ba(data.subarray(0, 100)))
            .update(_ba.ui8_to_ba(data.subarray(100, 250)))
            .update(_ba.ui8_to_ba(data.subarray(250)))
            .finalize();
        expect(streamed.length).toBe(8);
        for (let i = 0; i < 8; i++) {
            expect(streamed[i]).toBe(oneShot[i]);
        }
    });

    test('streaming clone constructor preserves IV + outWords', () => {
        const h1 = new _h.fn();
        h1.update('shared prefix - ');
        const h2 = new _h.fn(h1);
        h1.update('branch A');
        h2.update('branch B');
        const out1 = h1.finalize();
        const out2 = h2.finalize();
        expect(out1.length).toBe(8);
        expect(out2.length).toBe(8);
        // Cross-check vs one-shot
        const refA = _h.hash('shared prefix - branch A');
        const refB = _h.hash('shared prefix - branch B');
        for (let i = 0; i < 8; i++) {
            expect(out1[i]).toBe(refA[i]);
            expect(out2[i]).toBe(refB[i]);
        }
    });
});


